// Each file has one concern, so it stays at `FILE_MAX_LINES` or less, and a
// test file at `TEST_FILE_MAX_LINES` or less (design D18). Generated files are
// out of scope, by name or by the header of `just generate`.

import { expect, test } from "bun:test";
import fs from "node:fs";
import path from "node:path";
import { isGenerated } from "../../tools/generate.ts";
import { FILE_MAX_LINES, TEST_FILE_MAX_LINES } from "../../tools/limits.ts";
import { REPO, tmpDir } from "./repo.ts";

const TEXT = /\.(?:mjs|cjs|js|ts|json|jsonc|md|mdx|py|sh|toml|ya?ml|txt)$/;
// Files that a tool writes: the settings schemas of `just schema`, lock
// files, and the OpenSpec skills and commands of `openspec update`.
const GENERATED = [
  /^schemas\//,
  /(?:^|\/)(?:package-lock\.json|pnpm-lock\.yaml)$/,
  /^\.claude\/skills\/openspec-/,
  /^\.claude\/commands\/opsx\//,
];

function bound(file: string): number {
  return /\.test\.[^/]+$/.test(file) ? TEST_FILE_MAX_LINES : FILE_MAX_LINES;
}

/** The files under `root` that are over their bound, as "lines file". */
async function overBound(root: string, files: string[]): Promise<string[]> {
  const over = [];
  for (const f of files) {
    if (!TEXT.test(f) || GENERATED.some((g) => g.test(f))) continue;
    if (!fs.existsSync(path.join(root, f))) continue;
    const text = await Bun.file(path.join(root, f)).text();
    if (isGenerated(text)) continue;
    const lines = text.split("\n").length - (text.endsWith("\n") ? 1 : 0);
    if (lines > bound(f)) over.push(`${lines} ${f}`);
  }
  return over;
}

// A lint of the live repository.
test("lint: no repository file is over its line bound", async () => {
  // Tracked and untracked files that git does not ignore, so `external/`
  // and `node_modules/` are out.
  const r = Bun.spawnSync(
    ["git", "ls-files", "--cached", "--others", "--exclude-standard"],
    { cwd: REPO },
  );
  expect(r.exitCode).toBe(0);
  expect(
    await overBound(REPO, r.stdout.toString().split("\n").filter(Boolean)),
  ).toStrictEqual([]);
});

test("a file and a test file one line over the bound fail", async () => {
  const root = tmpDir("file-size");
  const write = (name: string, n: number) =>
    Bun.write(path.join(root, name), "x\n".repeat(n));
  await write("at.mjs", FILE_MAX_LINES);
  await write("over.mjs", FILE_MAX_LINES + 1);
  await write("at.test.mjs", TEST_FILE_MAX_LINES);
  await write("over.test.mjs", TEST_FILE_MAX_LINES + 1);
  fs.mkdirSync(path.join(root, "schemas"));
  await write("schemas/big.json", TEST_FILE_MAX_LINES + 1);
  const files = [
    "at.mjs",
    "over.mjs",
    "at.test.mjs",
    "over.test.mjs",
    "schemas/big.json",
  ];
  expect(await overBound(root, files)).toStrictEqual([
    `${FILE_MAX_LINES + 1} over.mjs`,
    `${TEST_FILE_MAX_LINES + 1} over.test.mjs`,
  ]);
});

test("Long generated file: a file with the header of `just generate` is out of the bound", async () => {
  const root = tmpDir("file-size-generated");
  const head = "<!-- Generated by `just generate` from `src/wiki/t.md`. -->\n";
  await Bun.write(path.join(root, "table.md"), head + "| x |\n".repeat(400));
  await Bun.write(path.join(root, "plain.md"), "| x |\n".repeat(400));
  expect(await overBound(root, ["table.md", "plain.md"])).toStrictEqual([
    "400 plain.md",
  ]);
});
